/**
 * PORT content model.
 *
 * `site.json` is generated by `npm run sync:content` and holds the raw pull of
 * portipoh.com (pages, paragraphs, images). This file is the editorial layer: it
 * curates that material into the stations you explore in the 3D space.
 *
 * To change wording, add an exhibit or reorder the space, edit `stations` below.
 * To refresh the underlying material, re-run `npm run sync:content`.
 */

import data from './site.json';

/* ------------------------------------------------------------------ raw types */

export type GalleryImage = {
  small: string;
  large: string;
  caption: string;
  width?: number;
  height?: number;
};

type RawImage = GalleryImage & { kind?: string; pageIds?: number[] };

type RawPage = {
  id: number;
  slug: string;
  title: string;
  parent: number;
  date: string;
  link: string;
  excerpt: string;
  paragraphs: string[];
  images: RawImage[];
  children: { id: number; slug: string; title: string }[];
};

type Raw = {
  generatedAt: string;
  source: string;
  counts: { pages: number; media: number; images: number };
  pages: RawPage[];
  images: RawImage[];
  terkini: {
    id: number;
    slug: string;
    title: string;
    date: string;
    paragraphs: string[];
    images: GalleryImage[];
  }[];
  portfolio: { id: number; slug: string; title: string; date: string; paragraphs: string[] }[];
};

const raw = data as unknown as Raw;

export const contentMeta = {
  generatedAt: raw.generatedAt,
  source: raw.source,
  counts: raw.counts,
};

/* ------------------------------------------------------------------ page helpers */

const pageById = new Map(raw.pages.map((p) => [p.id, p]));

export function page(id: number): RawPage | undefined {
  return pageById.get(id);
}

/** Elementor pages often lead with a title, breadcrumb and widget headings. */
const NOISE = new Set([
  'Home',
  'Selanjutnya',
  'Previous',
  'Next',
  'Bacaan Lanjut',
  'Daftar',
  'Pengenalan',
  'Objektif',
  'Konsep',
  'Impak',
  'Kesimpulan',
  'Video',
  'Ahli',
  'Lembaga',
  'Pengarah',
  'Pengurusan',
  'LOKASI KAMI',
]);

/** Real paragraphs from a page, with navigational debris removed. */
export function body(id: number, from = 0, count = 4): string[] {
  const p = pageById.get(id);
  if (!p) return [];
  const clean = p.paragraphs
    .map((s) => s.trim())
    .filter((s) => s.length > 24 && !NOISE.has(s) && s !== p.title);
  return clean.slice(from, from + count);
}

/** Every paragraph on a page, cleaned but uncapped. */
export function allBody(id: number): string[] {
  return body(id, 0, 200);
}

/** Images embedded on a given page. */
export function imagesOf(id: number, limit = 99): GalleryImage[] {
  const p = pageById.get(id);
  if (!p) return [];
  return p.images.slice(0, limit).map(({ small, large, caption, width, height }) => ({
    small,
    large,
    caption,
    width,
    height,
  }));
}

/** Standalone library assets (portraits, posters, partner logos, artwork shots). */
export function library(pattern: RegExp, limit = 8): GalleryImage[] {
  return raw.images
    .filter((i) => (i.kind === 'library' || !i.pageIds?.length) && pattern.test(i.caption))
    .slice(0, limit)
    .map(({ small, large, caption, width, height }) => ({ small, large, caption, width, height }));
}

/** Everything, de-duplicated — used for the welcome-stage backdrop. */
export const allImages: GalleryImage[] = raw.images.map(
  ({ small, large, caption, width, height }) => ({ small, large, caption, width, height }),
);

function dedupe(list: GalleryImage[]): GalleryImage[] {
  const seen = new Set<string>();
  return list.filter((img) => {
    if (seen.has(img.small)) return false;
    seen.add(img.small);
    return true;
  });
}

/* ------------------------------------------------------------------ station model */

export type GlyphKey =
  | 'compass'
  | 'stage'
  | 'brush'
  | 'frame'
  | 'wave'
  | 'beacon'
  | 'pin';

export type Exhibit = {
  id: string;
  title: string;
  meta: string;
  tagline: string;
  body: string[];
  bullets?: string[];
  images: GalleryImage[];
  /** Original page on portipoh.com, kept for "sumber asal" links. */
  source?: string;
};

export type StationSection = {
  heading: string;
  paragraphs: string[];
  bullets?: string[];
};

export type StationKind = 'corridor' | 'list' | 'about' | 'contact';

export type Station = {
  id: string;
  label: string;
  short: string;
  glyph: GlyphKey;
  accent: string;
  tagline: string;
  intro: string[];
  kind: StationKind;
  exhibits: Exhibit[];
  sections?: StationSection[];
  heroImage?: GalleryImage;
  partners?: GalleryImage[];
};

