/* ------------------------------------------------------------------ entrance frontage */

/**
 * Any image dropped into `src/assets/` named `entrance.*` is picked up automatically and
 * used as the PORT frontage in the approach and behind the entry screen. No code change
 * needed — just add the file and restart the dev server (or rebuild).
 */
const dropped = import.meta.glob('../assets/entrance.*', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

/** Program banner shipped by the live site — the fallback frontage. */
export const defaultEntranceImage: GalleryImage | undefined =
  library(/main_programme_header/i, 1)[0] ?? library(/header/i, 1)[0] ?? allImages[1];

/**
 * The photograph of PORT's front used in the approach sequence.
 *
 * Resolution order:
 *   1. `VITE_PORT_ENTRANCE=/some/url.jpg` in a `.env` file
 *   2. a file dropped at `src/assets/entrance.*`
 *   3. the banner synced from portipoh.com
 */
export const entranceImage: { large: string; small: string; caption: string } | undefined = (() => {
  const fromEnv = (import.meta.env.VITE_PORT_ENTRANCE as string | undefined)?.trim();
  if (fromEnv) return { large: fromEnv, small: fromEnv, caption: 'PORT' };
  const fromDisk = Object.values(dropped)[0];
  if (fromDisk) return { large: fromDisk, small: fromDisk, caption: 'PORT' };
  if (defaultEntranceImage) {
    return {
      large: defaultEntranceImage.large,
      small: defaultEntranceImage.small,
      caption: defaultEntranceImage.caption,
    };
  }
  return undefined;
})();

/** True when the frontage is a real dropped-in photo rather than the synced banner. */
export const entranceIsCustom = Boolean(
  (import.meta.env.VITE_PORT_ENTRANCE as string | undefined)?.trim() ||
    Object.values(dropped)[0],
);
